"""Loading and writing registry.bzl / git.bzl.

Public API
----------
- :func:`load_registry` — exec registry.bzl and return its ``REGISTRY`` list.
- :func:`load_git` — exec git.bzl and return its ``GIT`` list.
- :func:`write_registry` — sort + emit registry.bzl (``@generated`` header).
- :func:`alias_names` — set of alias crate names in a registry.
- :func:`git_crate_names` — set of normalised crate names provided by git.bzl.
- :func:`all_labels` — set of every registry label.
"""

from __future__ import annotations

from pathlib import Path
from typing import Any

from . import paths, starlark
from .resolve import assign_unique_labels, normalize


def load_registry(path: Path = paths.REGISTRY_BZL) -> list[dict[str, Any]]:
    """Execute the generated registry.bzl and return its REGISTRY list.

    The file contains only data (no side effects), so exec is acceptable here.
    """
    text = Path(path).read_text(encoding="utf-8")
    namespace: dict[str, Any] = {}
    exec(text, namespace)  # noqa: S102  # trusted, generated by this tool
    return namespace["REGISTRY"]


def load_git(path: Path = paths.GIT_BZL) -> list[dict[str, Any]]:
    """Execute git.bzl and return its GIT list (trusted, generated data)."""
    text = Path(path).read_text(encoding="utf-8")
    namespace: dict[str, Any] = {}
    exec(text, namespace)  # noqa: S102  # trusted
    return namespace["GIT"]


def write_registry(
    entries: list[dict[str, Any]], path: Path = paths.REGISTRY_BZL
) -> None:
    """Write ``entries`` to registry.bzl, sorted by (name.lower(), version)."""
    assign_unique_labels(entries)
    ordered = sorted(entries, key=lambda e: (e["name"].lower(), e["version"]))
    body = "\n".join(starlark.format_entry(e) for e in ordered)
    text = starlark.REGISTRY_HEADER + body + "\n]\n"
    Path(path).write_text(text, encoding="utf-8")


def alias_names(registry: list[dict[str, Any]]) -> set[str]:
    """{crate_name or normalize(name)} for every entry flagged ``alias``."""
    return {
        entry.get("crate_name") or normalize(entry["name"])
        for entry in registry
        if entry.get("alias")
    }


def git_crate_names(git: list[dict[str, Any]]) -> set[str]:
    """{normalize(name)} for every crate provided by a git repo in git.bzl."""
    return {
        normalize(crate["name"])
        for repo in git
        for crate in repo.get("crates", [])
    }


def all_labels(registry: list[dict[str, Any]]) -> set[str]:
    """The set of every ``label`` in the registry."""
    return {entry["label"] for entry in registry}
